WorkflowProcessEvent.eventDescription:
function beforeTaskSave(colleagueId,nextSequenceId,userList){
    hAPI.setCardValue("hd_solicitacao_atvAtual", nextSequenceId);

    var states = {
        next    : getValue("WKNextState"),
        actual  : getValue("WKNumState"),
        user    : getValue("WKUser")
    }
    
    if(states.actual == 10 && (states.next == 70 || states.next == 72)){
        var indexesAprov = hAPI.getChildrenIndexes("table_aprovadores");
        var indexesAlc   = hAPI.getChildrenIndexes("table_alcadas");
        var indexesPrd   = hAPI.getChildrenIndexes("table_produtos");
        var userProtheus = '';

        for (var i=0; i < indexesAprov.length; i++) {
            if(hAPI.getCardValue("hd_aprovador_codigoFluig___"+indexesAprov[i]) == states.user){
                hAPI.setCardValue("hd_aprovacao_dtDecisao___"+indexesAprov[i], formatarDataAtual(false));
                userProtheus = hAPI.getCardValue("hd_aprovador_codigoUsuario___"+indexesAprov[i]);
            }
        }
        
        for (var i=0; i < indexesAlc.length; i++) {
            if(userProtheus == hAPI.getCardValue("hd_alcada_codUsuario___"+indexesAlc[i]) && hAPI.getCardValue("hd_alcada_dtAprovacao___"+indexesAlc[i]) == ''){
                hAPI.setCardValue("hd_alcada_dtAprovacao___"+indexesAlc[i], formatarDataAtual(false));
            }
        }
    }
}

function formatarDataAtual(comHorario){
    var data = new Date();
    var dia  = data.getDate().toString(); dia = (dia.length>1)? dia : "0"+dia;
    var mes  = (data.getMonth()+1).toString(); mes = (mes.length>1)? mes : "0"+mes;
    var ano  = data.getFullYear();
    var hora = data.getHours().toString(); hora = (hora.length>1)? hora : "0"+hora;
    var minutos = data.getMinutes().toString(); minutos = (minutos.length>1)? minutos : "0"+minutos;
    if(comHorario){
        return dia+"/"+mes+"/"+ano + " " + hora+":"+minutos;
    }
    return dia+"/"+mes+"/"+ano;
}

function formatarDataEnAtual(comHorario){
    var data = new Date();
    var dia  = data.getDate().toString(); dia = (dia.length>1)? dia : "0"+dia;
    var mes  = (data.getMonth()+1).toString(); mes = (mes.length>1)? mes : "0"+mes;
    var ano  = data.getFullYear();
    var hora = data.getHours().toString(); hora = (hora.length>1)? hora : "0"+hora;
    var minutos = data.getMinutes().toString(); minutos = (minutos.length>1)? minutos : "0"+minutos;
    if(comHorario){
        return ano+"-"+mes+"-"+dia + " " + hora+":"+minutos;
    }
    return ano+"-"+mes+"-"+dia;
}

/****** 
** Enable customization script to change agreement calculation. 
** Input: 
**	stateId -> Current state, whose agreement percentage is being calculated. 
**	agreementData.get("currentPercentage") -> Current percentage, calculated by the workflow engine
**	agreementData.get("currentDestState") -> Current destination state. Zero, if process won't move
**	agreementData.get("currentDestUsers") -> Current destination users. Empty if process won't move
**/
function calculateAgreement(currentState, agreementData) {
	var indAprov = hAPI.getChildrenIndexes("table_aprovadores"), totalAprov = 0, user = getValue("WKUser"), nextTask = getValue("WKNextState"), codProcess = hAPI.getCardValue("lb_solicitacao_numero");
	var filtrosProtheus = [], strObs = '', strUserObs = '', aprovFeita = false, strAprovsPendentes = '';

	if(hAPI.getCardValue('hd_sc_encerradoProtheus') != 'true'){
		hAPI.setCardValue('hd_solicitacao_integraAlcadas', false);
		hAPI.setCardValue('hd_solicitacao_integraProdutos', false);
		hAPI.setCardValue('hd_solicitacao_pendenciaAprov', true);

		filtrosProtheus.push(DatasetFactory.createConstraint("processTaskPK.processInstanceId", codProcess, codProcess, ConstraintType.MUST));
		var dtsRetorno = DatasetFactory.getDataset("processTask", null, filtrosProtheus, null);
		if(dtsRetorno.rowsCount > 0){
			var lastComment = dtsRetorno.rowsCount-1;
			strObs = dtsRetorno.getValue(lastComment, "taskObservation");
			strUserObs = dtsRetorno.getValue(lastComment, "processTaskPK.colleagueId");
		}

		var indChat = hAPI.getChildrenIndexes("chat");
		if(strObs == "" && indChat.length > 0){
			var lastMsg = indChat.length-1;

			strObs     = hAPI.getCardValue('txta_observacoes___' + indChat[lastMsg]);
			strUserObs = hAPI.getCardValue('hd_login_user___' + indChat[lastMsg]);
		}

		for(var i=0; i < indAprov.length; i++){
			if(hAPI.getCardValue('hd_aprovador_codigoFluig___' + indAprov[i]) == user){
				aprovFeita = true;
				if(nextTask == 72){
					hAPI.setCardValue('hd_aprovador_statusAprovacao___' + indAprov[i], 'REPROVADO');
				}
				else{
					hAPI.setCardValue('hd_aprovador_statusAprovacao___' + indAprov[i], 'APROVADO');
				}

				if(user == strUserObs && strObs != ''){
					hAPI.setCardValue('hd_aprovacao_observacao___' + indAprov[i], strObs);
				}

				var aprovacoesFeitas = hAPI.getCardValue('hd_solicitacao_aprovsAtuados');
				if(aprovacoesFeitas != ''){
					aprovacoesFeitas += ',';
				}
				hAPI.setCardValue('hd_solicitacao_aprovsAtuados', aprovacoesFeitas + user);
			}
			
			if(hAPI.getCardValue('hd_aprovador_statusAprovacao___' + indAprov[i]) != ''){
				totalAprov++;
			}
			else{
				if(strAprovsPendentes != ''){
					strAprovsPendentes += ',';
				}
				strAprovsPendentes += hAPI.getCardValue('hd_aprovador_codigoFluig___' + indAprov[i]);

				
			}
		}

		hAPI.setCardValue('hd_aprov_gestorCusto', strAprovsPendentes);

		if(totalAprov == indAprov.length && totalAprov > 0){
			hAPI.setCardValue('hd_solicitacao_pendenciaAprov', false);
		}

		if(/*totalAprov == indAprov.length && totalAprov > 0*/aprovFeita){
			agreementData.put("currentPercentage", 100);
			agreementData.put("currentDestState", 70);
			agreementData.put("currentDestUsers", 'System:Auto');
		}
	}
	else{
		hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
		hAPI.setCardValue('hd_solicitacao_integraProdutos', true);
		hAPI.setCardValue('hd_solicitacao_pendenciaAprov', false);

		agreementData.put("currentPercentage", 100);
		agreementData.put("currentDestState", 70);
		agreementData.put("currentDestUsers", 'System:Auto');
	}
}

function servicetask35() {
    if(hAPI.getCardValue('hd_solicitacao_integraAlcadas') != 'true'){
        atualizaProtheusAlcadas();
    }
    else{
        // D6: com integraAlcadas ja true o atualizaProtheusAlcadas nao roda, e e la dentro
        // que o log e limpo. Sem isto o txta_observacoes_integracao guarda para sempre o
        // erro da ultima falha, e quem for diagnosticar depois le um erro ja resolvido
        // como se fosse a causa atual. O valor aqui e o diagnostico do estado corrente;
        // o historico fica no log do servidor.
        hAPI.setCardValue('txta_observacoes_integracao', "");
    }
}

/**
 * R2 - devolve o CR_STATUS quando a alcada JA esta processada no Protheus (03 ou 06),
 * ou string vazia em qualquer outro caso.
 *
 * Casa por CR_NUM + CR_FILIAL + CR_APROV. A filial e obrigatoria: o CR_NUM nao a
 * codifica e o mesmo numero de solicitacao existe em mais de uma filial; marcar pelo
 * registro da filial errada aprovaria a alcada errada.
 *
 * C_TIPO = 'SC' e obrigatorio: o dts_getScrMedicao_stg filtra CR_NUM por prefixo e sem
 * o tipo devolveria tambem medicoes e pedidos cujo numero comeca igual.
 *
 * Linha ausente da SCR devolve '' de proposito, mantendo a falha visivel. Tratar
 * ausencia como "ja processada" esconderia erro de chave.
 */
function statusAlcadaProtheus(empresa, filial, numDoc, codAprov) {
    try {
        var cNum  = DatasetFactory.createConstraint("C_MEDICAO",   numDoc,   numDoc,   ConstraintType.MUST);
        var cEmp  = DatasetFactory.createConstraint("CEMP",        empresa,  empresa,  ConstraintType.MUST);
        var cApr  = DatasetFactory.createConstraint("C_APROVADOR", codAprov, codAprov, ConstraintType.MUST);
        var cTipo = DatasetFactory.createConstraint("C_TIPO",      "SC",     "SC",     ConstraintType.MUST);

        var dts = DatasetFactory.getDataset("dts_getScrMedicao_stg", null, [cNum, cEmp, cApr, cTipo], null);

        if (dts == null || dts.rowsCount == 0) { return ''; }

        // getColumnsName devolve um ARRAY do Java (String[]): .length e o acesso por
        // indice funcionam sob Rhino, mas concatenar com string da o toString da JVM
        // e nao os nomes, entao indexOf sobre isso seria sempre -1.
        var cols = dts.getColumnsName();
        if (cols == null || (cols.length == 1 && (cols[0] + '') == 'ERRO')) { return ''; }

        for (var i = 0; i < dts.rowsCount; i++) {
            if (dts.getValue(i, 'CR_TIPO')   == 'SC' &&
                dts.getValue(i, 'CR_NUM')    == (numDoc + '') &&
                dts.getValue(i, 'CR_FILIAL') == (filial + '')) {

                var st = dts.getValue(i, 'CR_STATUS') + '';
                return (st == '03' || st == '06') ? st : '';
            }
        }
        return '';

    } catch (e) {
        log.info("statusAlcadaProtheus SC === " + e.toString());
        return '';
    }
}

/**
 * Descreve a alcada que o Protheus tem HOJE para este documento, em texto.
 *
 * Existe porque "Registro nao Localizado na Tabela - SCR" e honesta e inutil: o
 * APROVCOM casa por numero + aprovador + valor e a mensagem nao diz qual dos tres nao
 * bateu. Foram necessarias varias consultas manuais para descobrir, na solicitacao
 * 010668, que o numero estava certo e quem tinha mudado era o aprovador.
 *
 * Com esta linha no log, o proprio card passa a dizer:
 *   card manda aprovador 000012 / valor 18000
 *   Protheus tem aprovador 000038 / valor 1500
 *
 * Usa o mesmo dataset que a abertura usa - ja publicado e lendo da SCR -, em vez do
 * dts_getScrMedicao_stg, que e ferramenta de investigacao e pode nao estar no ar.
 *
 * A filial entra no filtro obrigatoriamente: o codigo de aprovador se repete entre
 * filiais, 000012 e uma pessoa diferente em cada uma.
 */
function descreveAlcadaProtheus(empresa, filial, numDoc) {
    try {
        var ds = DatasetFactory.getDataset("dts_getSolicComprasAlcadasItensProtheus_jynx", null, [
            DatasetFactory.createConstraint("C_NUMSOLIC", numDoc,  numDoc,  ConstraintType.MUST),
            DatasetFactory.createConstraint("C_EMP",      empresa, empresa, ConstraintType.MUST)
        ], null);

        if (ds == null || ds.rowsCount == 0) {
            return "o Protheus nao devolveu alcada para o numero " + numDoc;
        }

        // getColumnsName devolve array do Java; concatenar daria o toString da JVM.
        var cols = ds.getColumnsName(), temValor = false;
        if (cols != null) {
            for (var c = 0; c < cols.length; c++) {
                if ((cols[c] + '') == 'ALCADA_VALOR') { temValor = true; }
            }
        }
        if (!temValor) {
            return "consulta de alcada devolveu erro do Protheus (ver log do servidor)";
        }

        var txt = '';
        for (var i = 0; i < ds.rowsCount; i++) {
            if ((ds.getValue(i, 'FILIAL') + '').replace(/^\s+|\s+$/g, '') != (filial + '')) { continue; }
            txt += (txt ? ' ; ' : '') +
                   "aprovador " + ds.getValue(i, 'APROVADOR') +
                   " / usuario " + ds.getValue(i, 'APROVADOR_USER') +
                   " / valor " + ds.getValue(i, 'ALCADA_VALOR');
        }

        if (txt == '') {
            return "o Protheus nao tem alcada para o numero " + numDoc + " na filial " + filial;
        }
        return txt;

    } catch (e) {
        return "nao foi possivel consultar a alcada atual: " + e.toString();
    }
}

