                    valorAprov = "005"
                }
                obsAprov = hAPI.getCardValue('hd_aprovacao_observacao___' + indAprov[y]);

                // R3: o Protheus exige CR_OBS preenchido na reprovacao (operacao 005) e
                // recusa a chamada com "O campo Observacoes (CR_OBS) nao foi preenchido".
                // O Fluig permite reprovar sem comentario, entao sem este texto a
                // solicitacao trava em Trata falhas.
                if(obsAprov == '' && valorAprov == "005"){
                    obsAprov = "Reprovado no Fluig sem justificativa informada pelo aprovador "
                             + hAPI.getCardValue('hd_aprovador_nome___' + indAprov[y]);
                }

                indexActualAprov = indAprov[y];
            }
        }

        /*var cEmp    = DatasetFactory.createConstraint('C_EMPRESA',       empresa,     empresa , ConstraintType.MUST);
        var cFilial = DatasetFactory.createConstraint('C_FILIAL',        filial,      filial , ConstraintType.MUST);
        var cNum    = DatasetFactory.createConstraint('C_NUMERO_DOC',    codProtheus, codProtheus  , ConstraintType.MUST);
        var cTipo   = DatasetFactory.createConstraint('C_TIPO_DOC',      "SC",        "SC"   , ConstraintType.MUST);
        var cAprov  = DatasetFactory.createConstraint('C_APROVADOR_COD', codAprov,    codAprov, ConstraintType.MUST);
        var cOpc    = DatasetFactory.createConstraint('C_OPERACAO',      valorAprov,  valorAprov, ConstraintType.MUST);
        var cObs    = DatasetFactory.createConstraint('C_OBSERVACAO',    obsAprov,    obsAprov, ConstraintType.MUST);
        var dts     = DatasetFactory.getDataset('dts_setAprovacaoComprasProtheus_jynx', null, [cEmp, cFilial, cNum, cTipo, cAprov, cOpc, cObs], null);

        log.info("Aprovação SC ===")
        log.dir(dts)
        if(dts.rowsCount > 0 && dts.getValue(0, "STATUS") == "SUCESSO"){
            hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
            hAPI.setCardValue('hd_aprovacao_efetivada___' + indexActualAprov, true);
        }
        else{
            var c1 = DatasetFactory.createConstraint("C_NUMSOLIC", codProtheus, codProtheus, ConstraintType.MUST);
            var c2 = DatasetFactory.createConstraint("C_EMP", empresa, empresa, ConstraintType.MUST);
            var c3 = DatasetFactory.createConstraint("C_STATUS_ALCADA_ARR", "'03','06'", "'03','06'", ConstraintType.MUST);
            var c4 = DatasetFactory.createConstraint("C_FILIAL", filial, filial, ConstraintType.MUST);
            var c5 = DatasetFactory.createConstraint("C_APROVADOR", codAprov, codAprov, ConstraintType.MUST);
            var dtsRetorno = DatasetFactory.getDataset("dts_getSolicComprasAprovProtheus_jynx", null, [c1, c2, c3, c4, c5], null);

            if(dtsRetorno.rowsCount > 0 && dtsRetorno.getValue(0, "NUM_SOLIC") == (codProtheus + "") && dtsRetorno.getValue(0, "FILIAL") == (filial + "")){
                hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
                hAPI.setCardValue('hd_aprovacao_efetivada___' + indexActualAprov, true);
            }
            else if(dts.rowsCount > 0 && dts.getValue(0, "STATUS") == "ERRO"){
                hAPI.setCardValue('txta_observacoes_integracao', dts.getValue(0, "MENSAGEM") + "");
            }
        }*/

        hAPI.setCardValue('txta_observacoes_integracao', "");
        var totalPendentes = 0, totalAlcadas = 0;
        for (var z = 0; z < indAlcadas.length; z++) {
            if(codAprov == hAPI.getCardValue('hd_alcada_codAprovador___' + indAlcadas[z])){
                totalAlcadas++;
                if(hAPI.getCardValue('hd_alcada_descisao___' + indAlcadas[z]) == ""){
                    var codDoc  = hAPI.getCardValue('hd_alcada_numDocumento___' + indAlcadas[z]);
                    var valor   = hAPI.getCardValue('hd_alcada_valorItem___' + indAlcadas[z]);

                    var cEmp    = DatasetFactory.createConstraint('C_EMPRESA',       empresa,     empresa , ConstraintType.MUST);
                    var cFilial = DatasetFactory.createConstraint('C_FILIAL',        filial,      filial , ConstraintType.MUST);
                    var cNum    = DatasetFactory.createConstraint('C_NUMERO_DOC',    codDoc,      codDoc  , ConstraintType.MUST);
                    var cTipo   = DatasetFactory.createConstraint('C_TIPO_DOC',      "SC",        "SC"   , ConstraintType.MUST);
                    var cAprov  = DatasetFactory.createConstraint('C_APROVADOR_COD', codAprov,    codAprov, ConstraintType.MUST);
                    var cOpc    = DatasetFactory.createConstraint('C_OPERACAO',      valorAprov,  valorAprov, ConstraintType.MUST);
                    var cObs    = DatasetFactory.createConstraint('C_OBSERVACAO',    obsAprov,    obsAprov, ConstraintType.MUST);
                    var cValor  = DatasetFactory.createConstraint('C_VALOR_TOTAL',   valor,       valor, ConstraintType.MUST);
