                        // direto no Protheus. Nesse caso a API responde "Registro nao
                        // Localizado" e, sem esta verificacao, a solicitacao trava em Trata
                        // falhas para sempre: a decisao so e gravada por uma chamada
                        // bem-sucedida, que nunca mais vai acontecer porque o trabalho ja
                        // foi feito la.
                        var statusScr = statusAlcadaProtheus(empresa, filial, codDoc, codAprov);

                        if(statusScr != ''){
                            hAPI.setCardValue('hd_alcada_descisao___' + indAlcadas[z], valorAprov);
                            var msgOk = hAPI.getCardValue('txta_observacoes_integracao');
                            hAPI.setCardValue('txta_observacoes_integracao', msgOk + "\nAlcada " + codDoc +
                                " ja processada no Protheus (CR_STATUS " + statusScr +
                                ") - decisao " + valorAprov + " marcada sem nova chamada.");
                        }
                        else{
                            totalPendentes++;

                            // Junto da mensagem crua do Protheus, o que o card mandou e o
                            // que o Protheus tem. Sem isso o card so diz "Registro nao
                            // Localizado" e nao da para saber se o que mudou foi o numero,
                            // o aprovador ou o valor.
                            var comparacao = "\nO card enviou: aprovador " + codAprov +
                                             " / valor " + valor + " / documento " + codDoc +
                                             "\nO Protheus tem: " +
                                             descreveAlcadaProtheus(empresa, filial, codDoc);

                            var msgAtual = hAPI.getCardValue('txta_observacoes_integracao');
                            hAPI.setCardValue('txta_observacoes_integracao',
                                msgAtual + "\n" + dts.getValue(0, "MENSAGEM") + comparacao);
                        }
                    }
                }
            }
        }

        if(totalPendentes == 0 && totalAlcadas > 0){
            hAPI.setCardValue('hd_solicitacao_integraAlcadas', true);
            hAPI.setCardValue('hd_aprovacao_efetivada___' + indexActualAprov, true);

            var c1 = DatasetFactory.createConstraint("C_NUMSOLIC", codProtheus, codProtheus, ConstraintType.MUST);
            var c2 = DatasetFactory.createConstraint("C_EMP", empresa, empresa, ConstraintType.MUST);
            var c3 = DatasetFactory.createConstraint("C_FILIAL", filial, filial, ConstraintType.MUST);
            var dtsPrd = DatasetFactory.getDataset("dts_getSolicComprasProtheus_jynx", null, [c1, c2, c3], null);

            if(dtsPrd.rowsCount > 0 && dtsPrd.getValue(0, "NUM_SOLIC") == (codProtheus + "") && dtsPrd.getValue(0, "FILIAL") == (filial + "")){
                for(var i=0; i < dtsPrd.rowsCount; i++){
                    if(dtsPrd.getValue(i, "APROVACAO") != 'B' && hAPI.getCardValue("hd_produto_dtAprovacao___"+(i+1)) == ""){
                        hAPI.setCardValue("hd_produto_dtAprovacao___"+(i+1), formatarDataAtual(false));
                    }
                }
            }
        }
    } catch (e) {
        log.info("Erro serviceTask35 === " + e.toString())
    }
}

function formatarDataAtual(comHorario){
    var data = new Date();
    var dia  = data.getDate().toString(); dia = (dia.length>1)? dia : "0"+dia;
    var mes  = (data.getMonth()+1).toString(); mes = (mes.length>1)? mes : "0"+mes;
    var ano  = data.getFullYear();
    var hora = data.getHours().toString(); hora = (hora.length>1)? hora : "0"+hora;
    var minutos = data.getMinutes().toString(); minutos = (minutos.length>1)? minutos : "0"+minutos;
    if(comHorario){
        return dia+"/"+mes+"/"+ano + " " + hora+":"+minutos;
    }
    return dia+"/"+mes+"/"+ano;
}

/**
 * Confere aprovacao no Protheus - roda depois da integracao (servicetask35) ter dado certo.
 *
 * Mesma conferencia do aprovacaoMedicaoDeContratos.servicetask40, para a solicitacao de
 * compra: o APROVCOM responde "Registro Aprovado com Sucesso!" e as vezes nao grava nada
 * na SCR (casos reais em medicao: 002474, 002173, 002207 e 002258). O servicetask35 marca
 * a decisao so com a resposta, sem olhar a SCR.
 *
 * As alcadas com decisao marcada do aprovador que acabou de agir sao conferidas na SCR
 * (CR_TIPO 'SC'), na filial do card (ver aprovadorDaRodada):
 *   - decisao 001 (aprovar) precisa estar em 03; 005 (reprovar) precisa estar em 06.
 *   - tudo conferido: hd_conferencia_status = OK e o fluxo segue.
 *   - alguma divergente: a decisao dela e desmarcada, para o servicetask35 mandar de novo,
 *     e o resultado e REENVIAR. Depois de MAX_REENVIOS reenvios sem gravar, e FALHA e a
 *     solicitacao vai para Tratar Falhas com o motivo no txta_observacoes_integracao.
 *
 * Consulta que falha conta como NAO conferida: com os reenvios, uma queda rapida do
 * restqry e absorvida, e o Fluig nunca encerra uma solicitacao sem ver a SCR.
 */
var MAX_REENVIOS = 3;

function servicetask79(attempt, message) {
	try {
		// Encerrada ou editada no Protheus: o calculateAgreement ja decidiu sem chamar o
		// APROVCOM, e a SCR pode ter sido refeita. Nao ha o que conferir.
		var encerrado = hAPI.getCardValue("hd_sc_encerradoProtheus");
		if (encerrado == "true" || encerrado == "edit") {
			conferenciaOk();
			return;
		}

		var divergentes = alcadasNaoGravadas();
		if (divergentes.length == 0) {
			conferenciaOk();
			return;
		}

		var reenvios = parseInt(hAPI.getCardValue("hd_conferencia_reenvios"), 10);
		if (isNaN(reenvios)) {
			reenvios = 0;
		}

		var detalhe = "";
		for (var i = 0; i < divergentes.length; i++) {
			detalhe +=
				"\nAlcada " +
				divergentes[i].codDoc +
				" (aprovador " +
				divergentes[i].codAprov +
				"): " +
				divergentes[i].motivo;
		}

		if (reenvios < MAX_REENVIOS) {
			desmarcaDecisoes(divergentes);
			hAPI.setCardValue("hd_conferencia_reenvios", String(reenvios + 1));
			hAPI.setCardValue("hd_conferencia_status", "REENVIAR");
			log.info(
				"servicetask79 - solicitacao " +
					getValue("WKNumProces") +
					": reenvio " +
					(reenvios + 1) +
					" de " +
					MAX_REENVIOS +
					detalhe
			);
			return;
		}

		// Volta para o servicetask35 a partir de Tratar Falhas com a decisao desmarcada e o
		// contador zerado, ou seja, com mais MAX_REENVIOS tentativas.
		desmarcaDecisoes(divergentes);
		hAPI.setCardValue("hd_conferencia_reenvios", "0");
		hAPI.setCardValue("hd_conferencia_status", "FALHA");
		hAPI.setCardValue(
			"txta_observacoes_integracao",
			"O Protheus respondeu sucesso, mas a aprovacao nao foi gravada na SCR depois de " +
				MAX_REENVIOS +
				" reenvios. A solicitacao nao foi encerrada para a SC nao ficar aprovada " +
				"no Fluig e pendente no Protheus. Verificar no Protheus." +
				detalhe
		);
	} catch (e) {
		// Erro inesperado nao pode encerrar a solicitacao: vai para Tratar Falhas.
		log.info("Erro servicetask79 === " + e.toString());
		hAPI.setCardValue("hd_conferencia_status", "FALHA");
		hAPI.setCardValue("txta_observacoes_integracao", "Erro ao conferir a aprovacao no Protheus: " + e.toString());
	}
}

function conferenciaOk() {
	hAPI.setCardValue("hd_conferencia_reenvios", "0");
	hAPI.setCardValue("hd_conferencia_status", "OK");
}

/**
 * Alcadas do card com decisao marcada que a SCR nao confirma, agrupadas por documento +
 * aprovador (o card guarda uma linha por item; a SCR, uma por documento - ver servicetask35).
 */
function alcadasNaoGravadas() {
	var empresa = hAPI.getCardValue("hd_filial_codigo").trim();
	var filial = hAPI.getCardValue("hd_filial_codfil").trim();
	var numSolic = hAPI.getCardValue("hd_solicProtheus_codigo").trim();
	var indAlcadas = hAPI.getChildrenIndexes("table_alcadas");
	var aprovador = aprovadorDaRodada();

	var grupos = [],
		porChave = {};
	for (var i = 0; i < indAlcadas.length; i++) {
		var decisao = hAPI.getCardValue("hd_alcada_descisao___" + indAlcadas[i]);
		if (decisao == "") {
			continue;
		}
		var codDoc = hAPI.getCardValue("hd_alcada_numDocumento___" + indAlcadas[i]);
		var codAprov = hAPI.getCardValue("hd_alcada_codAprovador___" + indAlcadas[i]);
		if (aprovador != "" && codAprov != aprovador) {
			continue;
		}
		var chave = codDoc + "|" + codAprov;
		var g = porChave[chave];
		if (g == null) {
			g = { codDoc: codDoc, codAprov: codAprov, decisao: decisao, indices: [], motivo: "" };
			porChave[chave] = g;
			grupos.push(g);
		}
		g.indices.push(indAlcadas[i]);
	}

	if (grupos.length == 0) {
		return [];
	}

	var scr = statusScr(empresa, filial, numSolic);
	var divergentes = [];
	for (var k = 0; k < grupos.length; k++) {
		var grupo = grupos[k];
		var esperado = grupo.decisao == "005" ? "06" : "03";

		if (scr == null) {
			grupo.motivo = "nao foi possivel consultar a SCR";
		} else if (scr[grupo.codDoc + "|" + grupo.codAprov] == null) {
			grupo.motivo = "linha nao encontrada na SCR da filial " + filial;
		} else if (scr[grupo.codDoc + "|" + grupo.codAprov] != esperado) {
			grupo.motivo =
				"CR_STATUS " +
				scr[grupo.codDoc + "|" + grupo.codAprov] +
				", esperado " +
				esperado +
				" (decisao " +
				grupo.decisao +
				")";
		} else {
			continue;
		}
		divergentes.push(grupo);
	}
	return divergentes;
}

/**
 * Codigo Protheus do aprovador que acabou de agir: o ultimo login de
 * hd_solicitacao_aprovsAtuados (o calculateAgreement acrescenta um a cada aprovacao).
 *
 * So ele e conferido porque o servicetask35 reenvia um aprovador por vez - o ultimo da
 * tabela ainda nao efetivado. Desmarcar tambem a decisao de um aprovador anterior a
 * deixaria desmarcada para sempre, sem reenvio. Sem aprovador identificado, devolve '' e
 * todas as decisoes marcadas sao conferidas.
 */
function aprovadorDaRodada() {
	var atuados = hAPI.getCardValue("hd_solicitacao_aprovsAtuados").split(",");
	var login = atuados[atuados.length - 1].trim();
	if (login == "") {
		return "";
	}
	var indAprov = hAPI.getChildrenIndexes("table_aprovadores");
	for (var y = 0; y < indAprov.length; y++) {
		if (hAPI.getCardValue("hd_aprovador_codigoFluig___" + indAprov[y]) == login) {
			return hAPI.getCardValue("hd_aprovador_codigo___" + indAprov[y]);
		}
	}
	return "";
}

/**
 * CR_STATUS da SCR da solicitacao na filial do card, por "CR_NUM|CR_APROV", ou null se a
 * consulta falhar. Casa pela filial porque o mesmo numero de solicitacao existe em filiais
 * diferentes (comentario do servicetask35).
 */
function statusScr(empresa, filial, numSolic) {
	try {
		var dts = DatasetFactory.getDataset(
			"dts_getScrMedicao_stg",
			null,
			[
				DatasetFactory.createConstraint("C_MEDICAO", numSolic, numSolic, ConstraintType.MUST),
				DatasetFactory.createConstraint("CEMP", empresa, empresa, ConstraintType.MUST),
				DatasetFactory.createConstraint("C_TIPO", "SC", "SC", ConstraintType.MUST)
			],
			null
		);

		if (dts == null) {
			return null;
		}
		var cols = dts.getColumnsName();
		if (cols.length == 1 && cols[0] == "ERRO") {
			return null;
		}

		var mapa = {};
		for (var i = 0; i < dts.rowsCount; i++) {
			if (dts.getValue(i, "CR_FILIAL") + "" == filial) {
				mapa[dts.getValue(i, "CR_NUM") + "|" + dts.getValue(i, "CR_APROV")] = dts.getValue(i, "CR_STATUS") + "";
			}
		}
		return mapa;
	} catch (e) {
		log.info("statusScr servicetask79 === " + e.toString());
		return null;
	}
}

/**
 * Desfaz no card o que o servicetask35 marcou para as alcadas divergentes: a decisao da
 * alcada e o "efetivada" do aprovador. Sem isso o servicetask35 acha que nao ha nada a
 * enviar. integraAlcadas volta a false porque e o que faz o servicetask35 rodar de novo.
 */
function desmarcaDecisoes(divergentes) {
	var indAprov = hAPI.getChildrenIndexes("table_aprovadores");
	for (var i = 0; i < divergentes.length; i++) {
		for (var j = 0; j < divergentes[i].indices.length; j++) {
			hAPI.setCardValue("hd_alcada_descisao___" + divergentes[i].indices[j], "");
		}
		for (var y = 0; y < indAprov.length; y++) {
			if (hAPI.getCardValue("hd_aprovador_codigo___" + indAprov[y]) == divergentes[i].codAprov) {
				hAPI.setCardValue("hd_aprovacao_efetivada___" + indAprov[y], "false");
			}
		}
	}
	hAPI.setCardValue("hd_solicitacao_integraAlcadas", "false");
}
